CREATE TABLE emergency_requests(id UUID PRIMARY KEY,owner_user_id UUID NOT NULL,location VARCHAR(200) NOT NULL,summary VARCHAR(500) NOT NULL,status VARCHAR(30) NOT NULL,administrative_priority VARCHAR(30) NOT NULL,assigned_to UUID,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE emergency_events(id UUID PRIMARY KEY,request_id UUID NOT NULL REFERENCES emergency_requests(id),actor_user_id UUID NOT NULL,status VARCHAR(30) NOT NULL,administrative_priority VARCHAR(30) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
